import{_ as t,o as l,c as e,a as i}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"8. 计算机基础知识","description":"","frontmatter":{},"headers":[],"relativePath":"theory/08-computer.md","filePath":"theory/08-computer.md","lastUpdated":1787281221000}'),o={name:"theory/08-computer.md"};function r(d,a,s,n,h,p){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="_8-计算机基础知识" tabindex="-1">8. 计算机基础知识 <a class="header-anchor" href="#_8-计算机基础知识" aria-label="Permalink to &quot;8. 计算机基础知识&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能完成消防岗位常见的信息输入、文件管理、值班记录和简单表格操作，并知道账号、数据和记录为什么也需要安全管理。</p><h2 id="一、计算机由什么组成" tabindex="-1">一、计算机由什么组成 <a class="header-anchor" href="#一、计算机由什么组成" aria-label="Permalink to &quot;一、计算机由什么组成&quot;">​</a></h2><ul><li><strong>硬件</strong>：可以看到和触摸的设备，如主机、显示器、键盘、鼠标、打印机、硬盘。</li><li><strong>软件</strong>：运行在硬件上的程序。操作系统负责管理文件和设备，应用软件用于文字、表格、浏览器等具体工作。</li><li><strong>数据</strong>：报警记录、设备台账、维修记录和检测报告等信息。数据丢失或错误会影响交接班和故障追溯。</li></ul><h2 id="二、零基础理解-信息是怎样从现场变成可追溯记录的" tabindex="-1">二、零基础理解：信息是怎样从现场变成可追溯记录的 <a class="header-anchor" href="#二、零基础理解-信息是怎样从现场变成可追溯记录的" aria-label="Permalink to &quot;二、零基础理解：信息是怎样从现场变成可追溯记录的&quot;">​</a></h2><p>消防岗位中的计算机不是单纯的办公工具，而是把现场状态转换成可查询、可复核、可交接的信息系统。可以用四个环节理解：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：探测器、控制器、操作员录入、检测仪器读数</span></span>
<span class="line"><span>→ 处理：系统识别地址、分类状态、生成事件和日志</span></span>
<span class="line"><span>→ 存储：历史记录、值班记录、维修台账、检测报告</span></span>
<span class="line"><span>→ 输出：屏幕、声光提示、打印、导出、交接报告</span></span></code></pre></div><table tabindex="0"><thead><tr><th>概念</th><th>零基础理解</th><th>消防岗位例子</th></tr></thead><tbody><tr><td>文件</td><td>保存信息的载体</td><td>值班记录表、检测报告、设备说明书</td></tr><tr><td>文件夹</td><td>管理文件的容器</td><td>按月份或项目保存记录</td></tr><tr><td>数据库</td><td>按结构保存并检索大量记录的系统</td><td>控制器历史事件或设备台账</td></tr><tr><td>日志</td><td>按时间记录系统或操作事件</td><td>火警、故障、屏蔽、复位和登录记录</td></tr><tr><td>备份</td><td>在另一位置保留可恢复副本</td><td>定期备份值班记录和检测资料</td></tr></tbody></table><p>“复制一份”只是形成副本，不一定等于有效备份；备份还要考虑保存位置、时间、完整性、权限和能否恢复。删除历史记录也不能消除已经发生的火警或故障，只会破坏追溯证据。</p><h3 id="一个完整例子-从报警到交接" tabindex="-1">一个完整例子：从报警到交接 <a class="header-anchor" href="#一个完整例子-从报警到交接" aria-label="Permalink to &quot;一个完整例子：从报警到交接&quot;">​</a></h3><ol><li>探测器或手动报警按钮产生输入；</li><li>控制器识别设备地址并生成火警事件；</li><li>图形显示装置、声光设备或打印机输出信息；</li><li>操作员核实现场，把时间、地址、现象和处理过程写入值班记录；</li><li>维修或检测人员补充原因、措施、复测结果和恢复时间；</li><li>交接班人员核对控制器当前状态、未闭环事项和纸面/电子记录。</li></ol><p>如果屏幕显示、历史日志和现场现象不一致，应保留差异并分别核查，不能直接删除或修改原始记录来“统一口径”。</p><h2 id="二、文件管理练习" tabindex="-1">二、文件管理练习 <a class="header-anchor" href="#二、文件管理练习" aria-label="Permalink to &quot;二、文件管理练习&quot;">​</a></h2><p>用一个练习文件夹模拟值班资料：</p><ol><li>新建“值班记录”文件夹；</li><li>建立按日期命名的记录文件；</li><li>复制一份作为备份，不直接覆盖原始记录；</li><li>使用清晰的名称区分“原始记录、复核记录、整改记录”；</li><li>不随意删除或修改已经提交的记录。</li></ol><p>复制、移动、重命名和删除的区别要理解：复制产生副本，移动改变位置，重命名改变标识，删除可能使记录无法追溯。</p><h2 id="三、值班记录和表格" tabindex="-1">三、值班记录和表格 <a class="header-anchor" href="#三、值班记录和表格" aria-label="Permalink to &quot;三、值班记录和表格&quot;">​</a></h2><p>电子表格由工作簿、工作表、行、列和单元格组成。可以用表格记录时间、设备编号、状态、异常、处理人和复核人。</p><ul><li><code>SUM</code> 用于合计；</li><li><code>AVERAGE</code> 用于平均值；</li><li>排序和筛选用于查找某个设备、某一天或某种异常；</li><li>输入日期、设备编号和状态时要保持格式一致，避免同一设备出现多个写法。</li></ul><p>练习：建立 5 条虚拟报警记录，按设备编号筛选，再统计某一类报警数量。重点不是背快捷键，而是能让别人读懂并复核你的记录。</p><h2 id="四、账号和信息安全" tabindex="-1">四、账号和信息安全 <a class="header-anchor" href="#四、账号和信息安全" aria-label="Permalink to &quot;四、账号和信息安全&quot;">​</a></h2><p>消防控制室或考试系统可能使用个人账号。不要把账号密码写在公开位置、借给他人登录或在不明设备保存密码。记录中也可能包含建筑布局、设备地址和故障信息，应按单位制度管理。</p><h2 id="五、消防控制室信息系统的常见操作边界" tabindex="-1">五、消防控制室信息系统的常见操作边界 <a class="header-anchor" href="#五、消防控制室信息系统的常见操作边界" aria-label="Permalink to &quot;五、消防控制室信息系统的常见操作边界&quot;">​</a></h2><p>图形显示装置、值班电脑、打印机和控制器之间的显示内容可能因系统品牌和配置不同而不同，但学习时要抓住不变的判断逻辑：</p><ol><li>先确认事件类型、时间、设备地址或区域；</li><li>再查看相关历史记录、联动状态和反馈信息；</li><li>需要打印或导出时，保留原始记录并注明导出时间；</li><li>发现显示与现场不一致时，记录差异，不用截图或删除记录“修正”事实；</li><li>网络、打印或图形显示故障不能直接推断现场消防设施失效，应分别核查主机、通信、显示终端和现场设备。</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>不要把电脑显示“正常”当作现场设备一定正常，也不要为了消除故障提示而删除历史记录、重装系统或擅自修改权限。</p></div><h2 id="六、自测" tabindex="-1">六、自测 <a class="header-anchor" href="#六、自测" aria-label="Permalink to &quot;六、自测&quot;">​</a></h2><ol><li>复制和移动文件的区别是什么？</li><li>为什么值班记录不能随意覆盖原始文件？</li><li><code>SUM</code> 和 <code>AVERAGE</code> 分别解决什么问题？</li><li>消防设备地址和故障记录为什么不能随意公开？</li><li>图形显示装置故障时，为什么不能直接判定现场设施失效？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a> 2.2.7。</p></blockquote>`,30)])])}const u=t(o,[["render",r]]);export{b as __pageData,u as default};
